 selected=np.zeros((121,2),bool);selected[54,1]=True;observed=H['observed'].copy();observed[54,25:]=False;image=H['image_fit_valid'].copy();image[54,1]=False;side=H['side_valid'].copy();side[54,1]=False
 path=out/'best_near_surface_unaccepted.npz';np.savez_compressed(path,body_joint_names=H['body_joint_names'],body_joint_positions_rad_refined=q,base_xyz_m=C['base_xyz_m'],base_quaternion_xyzw=C['base_quaternion_xyzw'],actuator_names=H['actuator_names'],actuator_positions=a,actuator_units=H['actuator_units'],joint_names=H['joint_names'],joint_positions=coupling.expand_array(a),joint_units=H['joint_units'],timestamps=H['timestamps'],frame_indices=np.arange(121),refinement_selected_conditional=selected,refinement_accepted=np.zeros((121,2),bool),strict_acceptance_passed=np.asarray(False),image_fit_valid=image,side_valid=side,observed=observed,uncertain=~observed,source_body_sha256=np.asarray(sha(v2/'body_trajectory_contact.npz')),source_hand_sha256=np.asarray(sha(v2/'hand_trajectory_contact.npz')),source_camera_sha256=np.asarray(sha(v2/'camera_refinement.npz')),source_box_sha256=np.asarray(sha(v2/'box_trajectory.npz')),urdf_sha256=np.asarray(sha(kin.urdf_path)),coupling_math_sha256=np.asarray(sha(coupling.math_path)),observation_module_sha256=np.asarray(sha(ROOT/'scripts/user_hand_observations_v3.py')),source_trial_report_sha256=np.asarray(sha(rp)),candidate_is_metric_ground_truth=np.asarray(False))
 report={'status':'conditional_pareto_improvement_not_strictly_accepted','frame':54,'trial_seed':4,'source_actual_trial_report':{'path':str(rp),'sha256':sha(rp)},'source_bindings':r['source_bindings'],'baseline':r['baseline'],'actual_trial_metrics':t['metrics'],'remaining_rejections':t['rejections'],'joint_velocity_all_valid':True,'all_joint_position_limits_valid':True,'changed_body_joints':np.asarray(kin.body_joint_names)[arm].tolist(),'changed_actuators':H['actuator_names'][6:].tolist(),'unchanged_frames':[f for f in range(121)if f!=54],'gray_hand_observation_no_projection':True,'all_right_visual_surfaces':records,'strict_flags_not_promoted':True,'output':{'path':str(path),'sha256':sha(path)},'note':'Actually optimized trial 4 preserved exactly; source v2 unchanged. Physical nonpenetration improves, but hand_new_heldout4.689257 remains above unchanged4.5px criterion. Not an interpolated pose or a recovered metric grasp.'};(ROOT/'reports/user-frame54-near-surface-v3.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'output':report['output'],'metrics':t['metrics'],'min_full_surface_sdf_m':min(x['min_sdf_m']for x in records),'velocity_valid':True}),flush=True)
